function createGrade(kind,ps){if(state.grades.length>=30)return notice('動態操作最多 30 個，請先合併部分設計');try{let op=gradeParams(kind,ps);checkpoint();if(!state.grades.length)state.gradingSource=state.g.slice();state.grades.push(op);draft=[];gradeSelected=state.grades.length-1;setTool('editGrade');fillGradeForm();rebuildGrading()}catch(e){notice(e.message)}}
$('finishGrade').onclick=()=>{let kind={gradePlatform:'platform',gradePath:'path',gradePit:'pit',gradeRegion:'region'}[tool];if(!kind)return notice('請先選擇新增整坡類型');createGrade(kind,draft)};
$('updateGrade').onclick=()=>{let op=state.grades[gradeSelected];if(!op)return notice('請先選取整坡物件');if(op.locked)return notice('此物件已鎖定');try{let updated=gradeParams(op.kind,op.points);checkpoint();state.grades[gradeSelected]={...op,...updated,visible:op.visible,enabled:op.enabled,locked:op.locked};rebuildGrading();fillGradeForm()}catch(e){notice(e.message)}};
for(let[id,delta]of[['gradeUp',.5],['gradeDown',-.5]])$(id).onclick=()=>{let op=state.grades[gradeSelected];if(!op||op.locked)return notice('請選取未鎖定的物件');$('gradeZ').value=op.z+delta;$('gradeEndZ').value=op.endZ+delta;$('updateGrade').click()};
function renderGrades(){$('gradeList').replaceChildren();for(let[ i,op]of(state.grades||[]).entries()){let row=document.createElement('div');row.className='layer'+(i===gradeSelected?' gradeSelected':'');let top=document.createElement('div');top.className='layerTop';let title=document.createElement('span');title.textContent=(i+1)+'. '+op.name;let select=document.createElement('button');select.textContent=i===gradeSelected?'已選取':'選取';select.onclick=()=>{selectGrade(i);setTool('editGrade')};top.append(title,select);row.append(top);let options=document.createElement('div');options.className='layerOptions';for(let[key,label]of[['visible','顯示'],['enabled','啟用'],['locked','鎖定']]){let l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.checked=key==='locked'?!!op.locked:op[key]!==false;c.disabled=key==='enabled'&&op.locked;c.onchange=()=>{checkpoint();op[key]=c.checked;if(key==='enabled')rebuildGrading();else{paintGrades();renderGrades();fillGradeForm();drawAll()}};l.append(c,document.createTextNode(label));options.append(l)}row.append(options);let stats=gradeStats[i];if(stats){let text=document.createElement('div');text.className='gradeStats';text.textContent=`投影 ${fmt(stats.area)} m² / 表面 ${fmt(stats.surface)} m²｜挖 ${fmt(stats.cut)} m³ / 填 ${fmt(stats.fill)} m³`;row.append(text)}let actions=document.createElement('div');actions.className='layerActions';function btn(label,fn,disabled=false){let b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=fn;actions.append(b)}function order(d){checkpoint();let chosen=state.grades[gradeSelected];[state.grades[i],state.grades[i+d]]=[state.grades[i+d],state.grades[i]];gradeSelected=state.grades.indexOf(chosen);rebuildGrading()}
btn('↑',()=>order(-1),op.locked||i===0||state.grades[i-1]?.locked);btn('↓',()=>order(1),op.locked||i===state.grades.length-1||state.grades[i+1]?.locked);btn('複製',()=>{if(state.grades.length>=30)return notice('最多 30 個操作');checkpoint();let copy=JSON.parse(JSON.stringify(op));copy.name+=' 副本';copy.locked=false;state.grades.splice(i+1,0,copy);gradeSelected=i+1;rebuildGrading();fillGradeForm()});btn('刪除',()=>{checkpoint();state.grades.splice(i,1);gradeSelected=-1;gradeNode=-1;rebuildGrading();fillGradeForm()},op.locked);row.append(actions);$('gradeList').append(row)}}
function hitGrade(p){let tol=10/planT.scale,indices=state.grades.map((_,i)=>i).reverse();if(gradeSelected>=0)indices=[gradeSelected,...indices.filter(i=>i!==gradeSelected)];for(let i of indices){let op=state.grades[i];if(op.locked||op.visible===false)continue;for(let j=0;j<op.points.length;j++)if(Math.hypot(p[0]-op.points[j][0],p[1]-op.points[j][1])<tol)return{i,node:j}}for(let i of indices){let op=state.grades[i];if(op.locked||op.visible===false)continue;for(let j=0;j<op.points.length-(op.kind==='path'?1:0);j++){let q=closestSegment(p,op.points[j],op.points[(j+1)%op.points.length]);if(q.distance<tol)return{i,node:-1,segment:j,point:q.point}}}return null}
function startGradeDrag(e,p){let h=hitGrade(p);if(!h)return notice('請點選可見、未鎖定的整坡邊界');selectGrade(h.i);gradeNode=h.node;drag={type:'grade',index:h.i,node:h.node,start:p,points:state.grades[h.i].points.map(p=>p.slice()),changed:false};can.setPointerCapture(e.pointerId);drawAll()}
function moveGradeDrag(p){let d=drag,op=state.grades[d.index];if(!op||op.locked)return;let points=d.node<0?translated(d.points,p[0]-d.start[0],p[1]-d.start[1],state.w,state.h):op.points.map((q,i)=>i===d.node?[clamp(p[0],0,state.w),clamp(p[1],0,state.h)]:q);try{validateShape(points,op.kind!=='path',state.w,state.h)}catch(e){notice(e.message);return}if(!d.changed){checkpoint();d.changed=true}op.points=points;drawAll()}
let gradeDouble=can.ondblclick;can.ondblclick=e=>{if(tool!=='editGrade')return gradeDouble(e);let h=hitGrade(world(e));if(!h||h.node>=0)return;let op=state.grades[h.i];if(op.points.length>=300)return notice('節點上限 300');checkpoint();op.points.splice(h.segment+1,0,h.point);gradeSelected=h.i;gradeNode=h.segment+1;rebuildGrading()};
document.addEventListener('keydown',e=>{if(e.key!=='Delete'||tool!=='editGrade'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;let op=state.grades[gradeSelected];if(!op||op.locked||op.visible===false||gradeNode<0||gradeNode>=op.points.length)return;try{let ps=op.points.filter((_,i)=>i!==gradeNode);validateShape(ps,op.kind!=='path',state.w,state.h);e.preventDefault();checkpoint();op.points=ps;gradeNode=-1;rebuildGrading()}catch(e){notice(e.message)}});
$('bakeGrades').onclick=()=>{if(!state.grades.length)return notice('尚無動態整坡物件');checkpoint();state.grades=[];state.gradingSource=null;gradeSelected=-1;gradeStats=[];gradePaint=[];renderGrades();fillGradeForm();refresh();notice('已合併整坡結果，可繼續直接塑形；可使用復原取回動態物件')};
$('gradeReport').onclick=()=>{if(!state.grades.length)return notice('尚無動態整坡物件');let rows=['\uFEFF順序,名稱,類型,啟用,投影面積_m2,表面面積_m2,挖方_m3,填方_m3,淨土方_m3'];state.grades.forEach((op,i)=>{let v=gradeStats[i];rows.push([i+1,'"'+op.name.replaceAll('"','""')+'"',op.kind,op.enabled!==false,v.area,v.surface,v.cut,v.fill,v.net].join(','))});rows.push('"說明：各操作土方相對上一操作計算，重疊處可能重複挖填；最終基地淨變化請看主畫面填挖方。"');download('動態整坡面積土方.csv',rows.join('\n'),'text/csv')};

generate(true);buttons();setTool('inspect');
